// ============================================================================
// Root Store
// ============================================================================

export class RootStore {
  user: UserStore
  customer: CustomerStore
  pointsTransaction: PointsTransactionStore
  reward: RewardStore
  redemption: RedemptionStore
  staffUser: StaffUserStore
  loyaltySession: LoyaltySessionStore
  loyaltySettings: LoyaltySettingsStore

  constructor() {
    this.user = new UserStore()
    this.customer = new CustomerStore()
    this.pointsTransaction = new PointsTransactionStore()
    this.reward = new RewardStore()
    this.redemption = new RedemptionStore()
    this.staffUser = new StaffUserStore()
    this.loyaltySession = new LoyaltySessionStore()
    this.loyaltySettings = new LoyaltySettingsStore()
    makeAutoObservable(this)
  }

  /** Clear all stores */
  clearAll() {
    this.user.clear()
    this.customer.clear()
    this.pointsTransaction.clear()
    this.reward.clear()
    this.redemption.clear()
    this.staffUser.clear()
    this.loyaltySession.clear()
    this.loyaltySettings.clear()
  }
}

// ============================================================================
// Factory & Singleton
// ============================================================================

let rootStore: RootStore | null = null

/**
 * Get or create the root store singleton
 */
export function getStore(): RootStore {
  if (!rootStore) {
    rootStore = new RootStore()
  }
  return rootStore
}

/**
 * Create a new root store (for testing or SSR)
 */
export function createStore(): RootStore {
  return new RootStore()
}

/**
 * Reset the singleton store
 */
export function resetStore(): void {
  rootStore = null
}
